beforeSaveCustomScript:
$isVol = array\includes(contactType, 'Volunteer');
$isEmp = array\includes(contactType, 'Employee');
$isMem = array\includes(contactType, 'MemberContact');
$isPersonnel = $isVol || $isEmp;

if ($isPersonnel) {
    if (weeklyHours != null) {
        monthlyHours = number\round(weeklyHours * 4.33, 1);
    } else {
        monthlyHours = null;
    }
}
if ($isPersonnel && entity\isNew() && startDate == null) {
    startDate = datetime\today();
}
if ($isMem && entity\isNew() && joinDate == null) {
    joinDate = datetime\today();
}

$today = datetime\today();
if ($isPersonnel) {
    $startOk = ifThenElse(startDate == null, true, startDate <= $today);
    $endOk = ifThenElse(endDate == null, true, endDate >= $today);
    personnelStatus = ifThenElse($startOk && $endOk, 'Active', 'Inactive');
} else if ($isMem) {
    $startOk = ifThenElse(joinDate == null, true, joinDate <= $today);
    $endOk = ifThenElse(leaveDate == null, true, leaveDate >= $today);
    personnelStatus = ifThenElse($startOk && $endOk, 'Active', 'Inactive');
} else if (personnelStatus == null || personnelStatus == '') {
    personnelStatus = 'Active';
}
